function fmt(n) {
  return new Intl.NumberFormat("ar-SY").format(n) + " ل.س جديدة";
}

function useGoogleFonts() {
  useEffect(() => {
    const id = "mywheat-fonts";
    if (document.getElementById(id)) return;
    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Tajawal:wght@400;500;700;900&display=swap";
    document.head.appendChild(link);
  }, []);
}

function WheatMark({ size = 28, color = BRAND.gold }) {
  return <Wheat size={size} color={color} strokeWidth={2} />;
}

function PromoBanner() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const t = setInterval(() => {
      setIndex((i) => (i + 1) % PROMO_SLIDES.length);
    }, 4000);
    return () => clearInterval(t);
  }, []);

  function go(delta) {
    setIndex((i) => (i + delta + PROMO_SLIDES.length) % PROMO_SLIDES.length);
  }

  return (
    <div className="max-w-5xl mx-auto px-4 pt-3">
      <div className="relative w-full h-32 sm:h-40 rounded-2xl overflow-hidden shadow-md">
        {PROMO_SLIDES.map((s, i) => (
          <div
            key={i}
            style={{
              background: `linear-gradient(135deg, ${s.from}, ${s.to})`,
              opacity: i === index ? 1 : 0,
              transition: "opacity 0.6s ease",
            }}
            className="absolute inset-0 flex flex-col items-center justify-center text-center px-6"
          >
            <WheatMark size={30} color="#F7EFDA" />
            <div className="text-white font-bold text-lg sm:text-xl mt-1">{s.title}</div>
            <div className="text-[#F7EFDA] text-xs sm:text-sm mt-1">{s.subtitle}</div>
          </div>
        ))}

        <button
          onClick={() => go(-1)}
          className="absolute top-1/2 -translate-y-1/2 right-2 bg-black/25 hover:bg-black/40 transition rounded-full p-1.5"
          aria-label="السابق"
        >
          <ChevronRight size={16} color="#fff" />
        </button>
        <button
          onClick={() => go(1)}
          className="absolute top-1/2 -translate-y-1/2 left-2 bg-black/25 hover:bg-black/40 transition rounded-full p-1.5"
          aria-label="التالي"
        >
          <ChevronLeft size={16} color="#fff" />
        </button>

        <div className="absolute bottom-2 inset-x-0 flex items-center justify-center gap-1.5">
          {PROMO_SLIDES.map((_, i) => (
            <span
              key={i}
              onClick={() => setIndex(i)}
              style={{
                backgroundColor: i === index ? "#fff" : "rgba(255,255,255,0.5)",
                width: i === index ? 16 : 6,
                height: 6,
              }}
              className="rounded-full transition-all cursor-pointer"
            />
          ))}
        </div>
      </div>
    </div>
  );
}

// مفتاح فريد لعنصر السلة: معرّف المنتج + الحجم
function cartKey(productId, sizeLabel) {
  return `${productId}::${sizeLabel}`;
}

const ADMIN_PASSWORD = "wheat2026";

export default function MyWheatApp() {
  useGoogleFonts();

  const [view, setView] = useState("shop"); // shop | checkout | confirmed | admin
  const [adminUnlocked, setAdminUnlocked] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("owner") === "1") {
      const pass = window.prompt("أدخل كلمة مرور لوحة الإدارة:");
      if (pass === ADMIN_PASSWORD) {
        setAdminUnlocked(true);
        setView("admin");
      }
    }
  }, []);
  const [products, setProducts] = useState(DEFAULT_PRODUCTS);
  const [loadingProducts, setLoadingProducts] = useState(true);
  const [category, setCategory] = useState("الكل");
  const [cart, setCart] = useState({}); // { "id::size": qty }
  const [selectedSize, setSelectedSize] = useState({}); // { productId: sizeLabel }
  const [cartOpen, setCartOpen] = useState(false);
  const [form, setForm] = useState({ name: "", phone: "", address: "", notes: "" });
  const [placing, setPlacing] = useState(false);
  const [lastOrderId, setLastOrderId] = useState(null);
  const [orders, setOrders] = useState([]);
  const [loadingOrders, setLoadingOrders] = useState(false);
  const [savingKey, setSavingKey] = useState(null);

  // load products from shared storage, seed defaults if empty
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("mywheat-products-v2", true);
        if (res && res.value) {
          setProducts(JSON.parse(res.value));
        } else {
          await window.storage.set("mywheat-products-v2", JSON.stringify(DEFAULT_PRODUCTS), true);
          setProducts(DEFAULT_PRODUCTS);
        }
      } catch (e) {
        try {
          await window.storage.set("mywheat-products-v2", JSON.stringify(DEFAULT_PRODUCTS), true);
        } catch (_) {}
        setProducts(DEFAULT_PRODUCTS);
      } finally {
        setLoadingProducts(false);
      }
    })();
  }, []);

  const saveProducts = useCallback(async (next) => {
    setProducts(next);
    try {
      await window.storage.set("mywheat-products-v2", JSON.stringify(next), true);
    } catch (e) {
      console.error("تعذر حفظ المنتجات", e);
    }
  }, []);

  const loadOrders = useCallback(async () => {
    setLoadingOrders(true);
    try {
      const listRes = await window.storage.list("mywheat-orders:", true);
      const keys = (listRes && listRes.keys) || [];
      const results = [];
      for (const k of keys) {
        try {
          const r = await window.storage.get(k, true);
          if (r && r.value) results.push(JSON.parse(r.value));
        } catch (_) {}
      }
      results.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
      setOrders(results);
    } catch (e) {
      console.error("تعذر تحميل الطلبات", e);
      setOrders([]);
    } finally {
      setLoadingOrders(false);
    }
  }, []);

  useEffect(() => {
    if (view === "admin") loadOrders();
  }, [view, loadOrders]);

  const visibleProducts = useMemo(
    () => products.filter((p) => category === "الكل" || p.category === category),
    [products, category]
  );

  function getSize(product, label) {
    return product.sizes.find((s) => s.label === label);
  }

  function currentSizeLabel(product) {
    return selectedSize[product.id] || product.sizes[1]?.label || product.sizes[0]?.label;
  }

  const cartItems = useMemo(() => {
    return Object.entries(cart)
      .filter(([, qty]) => qty > 0)
      .map(([key, qty]) => {
        const [productId, sizeLabel] = key.split("::");
        const p = products.find((pp) => pp.id === productId);
        const s = p && getSize(p, sizeLabel);
        if (!p || !s) return null;
        return { key, productId, name: p.name, category: p.category, sizeLabel, price: s.price, qty };
      })
      .filter(Boolean);
  }, [cart, products]);

  const cartCount = cartItems.reduce((s, i) => s + i.qty, 0);
  const cartTotal = cartItems.reduce((s, i) => s + i.qty * i.price, 0);

  function changeQty(productId, sizeLabel, delta) {
    const key = cartKey(productId, sizeLabel);
    setCart((prev) => {
      const current = prev[key] || 0;
      const next = Math.max(0, current + delta);
      return { ...prev, [key]: next };
    });
  }

  const WHATSAPP_NUMBER = "963957289271";

  async function placeOrder(e) {
    e.preventDefault();
    if (!form.name.trim() || !form.phone.trim() || cartItems.length === 0) return;
    setPlacing(true);
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

    const lines = [];
    lines.push("طلب جديد من ماي ويت");
    lines.push(`رقم الطلب: ${id}`);
    lines.push("");
    lines.push(`الاسم: ${form.name.trim()}`);
    lines.push(`الهاتف: ${form.phone.trim()}`);
    if (form.address.trim()) lines.push(`العنوان: ${form.address.trim()}`);
    if (form.notes.trim()) lines.push(`ملاحظات: ${form.notes.trim()}`);
    lines.push("");
    lines.push("المنتجات:");
    cartItems.forEach((i) => {
      lines.push(`- ${i.name} (${i.sizeLabel}) × ${i.qty} = ${fmt(i.price * i.qty)}`);
    });
    lines.push("");
    lines.push(`الإجمالي: ${fmt(cartTotal)}`);

    const message = encodeURIComponent(lines.join("\n"));
    const waUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${message}`;

    setLastOrderId(id);
    window.open(waUrl, "_blank");
    setCart({});
    setView("confirmed");
    setPlacing(false);
  }

  async function updateOrderStatus(order, status) {
    const next = { ...order, status };
    try {
      await window.storage.set(`mywheat-orders:${order.id}`, JSON.stringify(next), true);
      setOrders((prev) => prev.map((o) => (o.id === order.id ? next : o)));
    } catch (e) {
      console.error("تعذر تحديث حالة الطلب", e);
    }
  }

  async function updateSize(productId, sizeLabel, patch) {
    const key = cartKey(productId, sizeLabel);
    setSavingKey(key);
    const next = products.map((p) => {
      if (p.id !== productId) return p;
      return {
        ...p,
        sizes: p.sizes.map((s) => (s.label === sizeLabel ? { ...s, ...patch } : s)),
      };
    });
    await saveProducts(next);
    setSavingKey(null);
  }

  return (
    <div
      dir="rtl"
      style={{ backgroundColor: BRAND.cream, fontFamily: "'Tajawal', sans-serif", minHeight: "100vh" }}
      className="text-right"
    >
      {/* Logo Banner */}
      <img
        src="data:image/jpeg;base64,"
        alt="ماي ويت"
        className="w-full h-auto block"
      />

      {/* Header */}
      <header style={{ backgroundColor: BRAND.brown }} className="sticky top-0 z-30 shadow-md">
        <div className="max-w-5xl mx-auto px-4 py-3 flex items-center justify-between">
          <button onClick={() => setView("shop")} className="flex items-center gap-2">
            <WheatMark size={26} color={BRAND.gold} />
            <div className="leading-tight text-right">
              <div style={{ fontFamily: "'Amiri', serif", color: BRAND.gold }} className="text-lg font-bold">
                ماي ويت
              </div>
              <div style={{ color: "#E8D9BE" }} className="text-[11px]">
                مؤسسة القمحة الذهبية
              </div>
            </div>
          </button>

          <div className="flex items-center gap-2">
            {adminUnlocked && (
              <button
                onClick={() => setView(view === "admin" ? "shop" : "admin")}
                className="p-2 rounded-full hover:bg-white/10 transition"
                title="لوحة الإدارة"
              >
                <Settings size={20} color="#E8D9BE" />
              </button>
            )}
            {view !== "admin" && (
              <button onClick={() => setCartOpen(true)} className="relative p-2 rounded-full hover:bg-white/10 transition">
                <ShoppingCart size={20} color="#E8D9BE" />
                {cartCount > 0 && (
                  <span
                    style={{ backgroundColor: BRAND.rust }}
                    className="absolute -top-1 -left-1 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center"
                  >
                    {cartCount}
                  </span>
                )}
              </button>
            )}
          </div>
        </div>
      </header>

      {view === "shop" && (
        <>
          {/* Promo banner carousel */}
          <PromoBanner />

          {/* Categories — icon grid */}
          <div className="max-w-5xl mx-auto px-2 pt-4 pb-2">
            <div className="flex gap-4 overflow-x-auto no-scrollbar px-2">
              {CATEGORIES.map((c) => {
                const active = c === category;
                const Icon = CATEGORY_ICONS[c] || LayoutGrid;
                return (
                  <button
                    key={c}
                    onClick={() => setCategory(c)}
                    className="flex flex-col items-center gap-1.5 shrink-0"
                  >
                    <span
                      style={{
                        backgroundColor: active ? BRAND.gold : BRAND.creamCard,
                        borderColor: active ? BRAND.gold : "rgba(62,42,23,0.15)",
                      }}
                      className="w-16 h-16 rounded-full border-2 flex items-center justify-center shadow-sm transition"
                    >
                      <Icon size={26} color={active ? BRAND.brown : BRAND.brownSoft} />
                    </span>
                    <span
                      style={{ color: active ? BRAND.brown : BRAND.brownSoft }}
                      className="text-[11px] font-bold whitespace-nowrap"
                    >
                      {c}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Product grid */}
          <main className="max-w-5xl mx-auto px-4 py-6">
            {loadingProducts ? (
              <div className="flex items-center justify-center py-24" style={{ color: BRAND.brownSoft }}>
                <Loader2 className="animate-spin ml-2" size={22} /> جاري تحميل المنتجات...
              </div>
            ) : (
              <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
                {visibleProducts.map((p) => {
                  const sizeLabel = currentSizeLabel(p);
                  const size = getSize(p, sizeLabel);
                  const key = cartKey(p.id, sizeLabel);
                  const qty = cart[key] || 0;
                  const displayImage = (p.sizeImages && p.sizeImages[sizeLabel]) || p.image;
                  return (
                    <div
                      key={p.id}
                      style={{ backgroundColor: BRAND.creamCard, borderColor: "rgba(62,42,23,0.08)" }}
                      className="rounded-2xl border overflow-hidden flex flex-col justify-between shadow-sm hover:shadow-lg transition-shadow duration-200"
                    >
                      {displayImage && (
                        <div
                          className="relative w-full aspect-square flex items-center justify-center p-3"
                          style={{ backgroundColor: BRAND.cream }}
                        >
                          <img
                            src={displayImage}
                            alt={`${p.name} ${sizeLabel}`}
                            className="w-full h-full object-contain"
                            style={{ filter: "drop-shadow(0 6px 10px rgba(62,42,23,0.18))" }}
                          />
                        </div>
                      )}
                      <div className="p-2.5 sm:p-4 flex flex-col justify-between flex-1">
                      <div>
                        <div style={{ color: BRAND.goldDark }} className="text-[11px] font-bold mb-1">
                          {p.category}
                        </div>
                        <div style={{ color: BRAND.brown }} className="font-bold text-sm sm:text-base leading-snug">
                          {p.name}
                        </div>

                        {/* Size selector */}
                        <div className="flex flex-wrap gap-1.5 mt-2">
                          {p.sizes.map((s) => {
                            const active = s.label === sizeLabel;
                            return (
                              <button
                                key={s.label}
                                onClick={() => setSelectedSize((prev) => ({ ...prev, [p.id]: s.label }))}
                                disabled={!s.inStock}
                                style={{
                                  backgroundColor: active ? BRAND.brown : "transparent",
                                  color: active ? "#E8D9BE" : s.inStock ? BRAND.brownSoft : "#C9C0AE",
                                  borderColor: active ? BRAND.brown : "rgba(62,42,23,0.25)",
                                }}
                                className="text-[10px] font-bold px-2 py-1 rounded-full border disabled:line-through"
                              >
                                {s.label}
                              </button>
                            );
                          })}
                        </div>
                      </div>

                      <div className="mt-4 flex items-center justify-between">
                        <span style={{ color: BRAND.rust }} className="font-extrabold text-sm">
                          {size ? fmt(size.price) : "—"}
                        </span>

                        {!size || !size.inStock ? (
                          <span className="flex items-center gap-1 text-xs font-bold text-stone-400">
                            <PackageX size={14} /> غير متوفر
                          </span>
                        ) : qty === 0 ? (
                          <button
                            onClick={() => changeQty(p.id, sizeLabel, 1)}
                            style={{ backgroundColor: BRAND.gold, color: BRAND.brown }}
                            className="text-xs font-bold px-3 py-1.5 rounded-full flex items-center gap-1 hover:opacity-90 transition"
                          >
                            <Plus size={14} /> أضف
                          </button>
                        ) : (
                          <div style={{ backgroundColor: BRAND.brown }} className="flex items-center gap-3 rounded-full px-2 py-1">
                            <button onClick={() => changeQty(p.id, sizeLabel, 1)}>
                              <Plus size={14} color={BRAND.gold} />
                            </button>
                            <span className="text-white text-xs font-bold w-4 text-center">{qty}</span>
                            <button onClick={() => changeQty(p.id, sizeLabel, -1)}>
                              <Minus size={14} color={BRAND.gold} />
                            </button>
                          </div>
                        )}
                      </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </main>

          {/* Floating checkout bar */}
          {cartCount > 0 && (
            <div className="fixed bottom-0 inset-x-0 z-30 px-4 pb-4">
              <button
                onClick={() => setCartOpen(true)}
                style={{ backgroundColor: BRAND.rust }}
                className="max-w-5xl mx-auto w-full text-white font-bold rounded-2xl py-3.5 flex items-center justify-between px-5 shadow-lg"
              >
                <span className="flex items-center gap-2">
                  <ShoppingCart size={18} /> عرض السلة ({cartCount})
                </span>
                <span>{fmt(cartTotal)}</span>
              </button>
            </div>
          )}
        </>
      )}

      {/* Cart drawer */}
      {cartOpen && (
        <div className="fixed inset-0 z-40 flex">
          <div className="flex-1 bg-black/40" onClick={() => setCartOpen(false)} />
          <div style={{ backgroundColor: BRAND.cream }} className="w-full max-w-sm h-full overflow-y-auto shadow-2xl flex flex-col">
            <div style={{ backgroundColor: BRAND.brown }} className="flex items-center justify-between p-4">
              <span className="text-white font-bold">سلة الطلبات</span>
              <button onClick={() => setCartOpen(false)}>
                <X size={20} color="#E8D9BE" />
              </button>
            </div>

            <div className="flex-1 p-4 space-y-3">
              {cartItems.length === 0 ? (
                <div style={{ color: BRAND.brownSoft }} className="text-center py-16 text-sm">
                  سلتك فارغة حاليًا
                </div>
              ) : (
                cartItems.map((i) => (
                  <div key={i.key} style={{ backgroundColor: BRAND.creamCard }} className="rounded-xl p-3 flex items-center justify-between">
                    <div>
                      <div style={{ color: BRAND.brown }} className="font-bold text-sm">
                        {i.name}
                      </div>
                      <div style={{ color: BRAND.brownSoft }} className="text-xs">
                        {i.sizeLabel} · {fmt(i.price)}
                      </div>
                    </div>
                    <div style={{ backgroundColor: BRAND.brown }} className="flex items-center gap-3 rounded-full px-2 py-1">
                      <button onClick={() => changeQty(i.productId, i.sizeLabel, 1)}>
                        <Plus size={13} color={BRAND.gold} />
                      </button>
                      <span className="text-white text-xs font-bold w-4 text-center">{i.qty}</span>
                      <button onClick={() => changeQty(i.productId, i.sizeLabel, -1)}>
                        <Minus size={13} color={BRAND.gold} />
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>

            {cartItems.length > 0 && (
              <div className="p-4 border-t" style={{ borderColor: "rgba(62,42,23,0.12)" }}>
                <div className="flex items-center justify-between mb-3">
                  <span style={{ color: BRAND.brown }} className="font-bold">
                    الإجمالي
                  </span>
                  <span style={{ color: BRAND.rust }} className="font-extrabold">
                    {fmt(cartTotal)}
                  </span>
                </div>
                <button
                  onClick={() => {
                    setCartOpen(false);
                    setView("checkout");
                  }}
                  style={{ backgroundColor: BRAND.gold, color: BRAND.brown }}
                  className="w-full font-bold py-3 rounded-xl flex items-center justify-center gap-2"
                >
                  متابعة الطلب <ArrowRight size={16} />
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Checkout */}
      {view === "checkout" && (
        <main className="max-w-md mx-auto px-4 py-8">
          <button onClick={() => setView("shop")} style={{ color: BRAND.brownSoft }} className="flex items-center gap-1 text-sm mb-4">
            <ArrowRight size={16} /> رجوع للمتجر
          </button>

          <h2 style={{ fontFamily: "'Amiri', serif", color: BRAND.brown }} className="text-2xl font-bold mb-4">
            بيانات التوصيل
          </h2>

          <form onSubmit={placeOrder} className="space-y-3">
            <Field icon={<User size={16} />} placeholder="الاسم الكامل" value={form.name} onChange={(v) => setForm((f) => ({ ...f, name: v }))} required />
            <Field icon={<Phone size={16} />} placeholder="رقم الهاتف" value={form.phone} onChange={(v) => setForm((f) => ({ ...f, phone: v }))} required type="tel" />
            <Field icon={<MapPin size={16} />} placeholder="العنوان / المنطقة" value={form.address} onChange={(v) => setForm((f) => ({ ...f, address: v }))} />
            <Field icon={<StickyNote size={16} />} placeholder="ملاحظات (اختياري)" value={form.notes} onChange={(v) => setForm((f) => ({ ...f, notes: v }))} textarea />

            <div style={{ backgroundColor: BRAND.creamCard }} className="rounded-xl p-4 mt-4">
              {cartItems.map((i) => (
                <div key={i.key} className="flex justify-between text-sm py-1">
                  <span style={{ color: BRAND.brownSoft }}>
                    {i.name} ({i.sizeLabel}) × {i.qty}
                  </span>
                  <span style={{ color: BRAND.brown }} className="font-bold">
                    {fmt(i.price * i.qty)}
                  </span>
                </div>
              ))}
              <div className="flex justify-between pt-2 mt-2 border-t" style={{ borderColor: "rgba(62,42,23,0.15)" }}>
                <span style={{ color: BRAND.brown }} className="font-bold">
                  الإجمالي
                </span>
                <span style={{ color: BRAND.rust }} className="font-extrabold">
                  {fmt(cartTotal)}
                </span>
              </div>
            </div>

            <button
              type="submit"
              disabled={placing || !form.name.trim() || !form.phone.trim()}
              style={{ backgroundColor: BRAND.rust }}
              className="w-full text-white font-bold py-3.5 rounded-xl flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {placing ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}
              تأكيد الطلب
            </button>
          </form>
        </main>
      )}

      {/* Confirmation */}
      {view === "confirmed" && (
        <main className="max-w-md mx-auto px-4 py-16 text-center">
          <div style={{ backgroundColor: BRAND.gold }} className="h-16 w-16 rounded-full flex items-center justify-center mx-auto mb-5">
            <Check size={30} color={BRAND.brown} />
          </div>
          <h2 style={{ fontFamily: "'Amiri', serif", color: BRAND.brown }} className="text-2xl font-bold mb-2">
            تم استلام طلبك
          </h2>
          <p style={{ color: BRAND.brownSoft }} className="text-sm mb-1">
            رقم الطلب: {lastOrderId}
          </p>
          <p style={{ color: BRAND.brownSoft }} className="text-sm mb-6">
            سيتواصل معك فريق ماي ويت لتأكيد التوصيل.
          </p>
          <button onClick={() => setView("shop")} style={{ backgroundColor: BRAND.brown }} className="text-white font-bold px-6 py-3 rounded-xl">
            متابعة التسوّق
          </button>
        </main>
      )}

      {/* Admin */}
      {view === "admin" && (
        <main className="max-w-5xl mx-auto px-4 py-6">
          <div className="flex items-center gap-2 mb-6">
            <ClipboardList size={20} color={BRAND.brown} />
            <h2 style={{ fontFamily: "'Amiri', serif", color: BRAND.brown }} className="text-xl font-bold">
              لوحة الإدارة
            </h2>
          </div>
          <p style={{ color: BRAND.brownSoft }} className="text-xs mb-6">
            ملاحظة: هذه اللوحة غير محمية بكلمة مرور — أي شخص لديه رابط التطبيق يمكنه الوصول إليها.
          </p>

          <section className="mb-10">
            <h3 style={{ color: BRAND.brown }} className="font-bold mb-3">
              الطلبات الواردة
            </h3>
            {loadingOrders ? (
              <div className="flex items-center gap-2 text-sm" style={{ color: BRAND.brownSoft }}>
                <Loader2 className="animate-spin" size={16} /> جاري التحميل...
              </div>
            ) : orders.length === 0 ? (
              <div style={{ color: BRAND.brownSoft }} className="text-sm">
                لا توجد طلبات بعد.
              </div>
            ) : (
              <div className="space-y-3">
                {orders.map((o) => (
                  <div key={o.id} style={{ backgroundColor: BRAND.creamCard, borderColor: "rgba(62,42,23,0.1)" }} className="rounded-xl border p-4">
                    <div className="flex flex-wrap items-center justify-between gap-2 mb-2">
                      <div>
                        <span style={{ color: BRAND.brown }} className="font-bold">
                          {o.customer}
                        </span>
                        <span style={{ color: BRAND.brownSoft }} className="text-xs mr-2">
                          {o.phone}
                        </span>
                      </div>
                      <select
                        value={o.status}
                        onChange={(e) => updateOrderStatus(o, e.target.value)}
                        style={{ borderColor: BRAND.gold, color: BRAND.brown }}
                        className="text-xs font-bold rounded-full border px-3 py-1 bg-transparent"
                      >
                        <option value="جديد">جديد</option>
                        <option value="قيد التجهيز">قيد التجهيز</option>
                        <option value="تم التوصيل">تم التوصيل</option>
                        <option value="ملغى">ملغى</option>
                      </select>
                    </div>
                    {o.address && (
                      <div style={{ color: BRAND.brownSoft }} className="text-xs mb-1">
                        📍 {o.address}
                      </div>
                    )}
                    {o.notes && (
                      <div style={{ color: BRAND.brownSoft }} className="text-xs mb-1">
                        ملاحظة: {o.notes}
                      </div>
                    )}
                    <div className="text-xs mt-2 space-y-0.5">
                      {o.items.map((it, idx) => (
                        <div key={idx} style={{ color: BRAND.brownSoft }} className="flex justify-between">
                          <span>
                            {it.name} ({it.size}) × {it.qty}
                          </span>
                          <span>{fmt(it.price * it.qty)}</span>
                        </div>
                      ))}
                    </div>
                    <div className="flex justify-between mt-2 pt-2 border-t" style={{ borderColor: "rgba(62,42,23,0.12)" }}>
                      <span style={{ color: BRAND.brown }} className="font-bold text-sm">
                        الإجمالي
                      </span>
                      <span style={{ color: BRAND.rust }} className="font-extrabold text-sm">
                        {fmt(o.total)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </section>

          <section>
            <h3 style={{ color: BRAND.brown }} className="font-bold mb-3">
              إدارة المنتجات والأسعار
            </h3>
            <p style={{ color: BRAND.brownSoft }} className="text-xs mb-3">
              كل صنف متوفر بالأحجام: 30g / 160g / 220g / 350g / كيس 250g. الأسعار تقديرية — عدّلها هنا لتُحدَّث فورًا.
            </p>
            <div className="space-y-3">
              {products.map((p) => (
                <div key={p.id} style={{ backgroundColor: BRAND.creamCard, borderColor: "rgba(62,42,23,0.1)" }} className="rounded-xl border p-3">
                  <div style={{ color: BRAND.brown }} className="font-bold text-sm mb-2">
                    {p.name} <span style={{ color: BRAND.brownSoft }} className="font-normal">· {p.category}</span>
                  </div>
                  <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
                    {p.sizes.map((s) => {
                      const key = cartKey(p.id, s.label);
                      return (
                        <div key={s.label} style={{ borderColor: "rgba(62,42,23,0.15)" }} className="rounded-lg border p-2">
                          <div style={{ color: BRAND.brownSoft }} className="text-[10px] font-bold mb-1">
                            {s.label}
                          </div>
                          <input
                            type="number"
                            value={s.price}
                            onChange={(e) => updateSize(p.id, s.label, { price: Number(e.target.value) || 0 })}
                            style={{ borderColor: BRAND.gold, color: BRAND.brown }}
                            className="w-full text-xs font-bold rounded-lg border px-1.5 py-1 bg-transparent mb-1"
                          />
                          <button
                            onClick={() => updateSize(p.id, s.label, { inStock: !s.inStock })}
                            style={{ backgroundColor: s.inStock ? BRAND.green : "#B9AE99", color: "white" }}
                            className="w-full text-[9px] font-bold px-1 py-1 rounded-md"
                          >
                            {s.inStock ? "متوفر" : "غير متوفر"}
                          </button>
                          {savingKey === key && <Loader2 className="animate-spin mx-auto mt-1" size={12} color={BRAND.brownSoft} />}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </section>
        </main>
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
}

function Field({ icon, placeholder, value, onChange, required, type = "text", textarea }) {
  const commonStyle = {
    borderColor: "rgba(62,42,23,0.2)",
    color: BRAND.brown,
    backgroundColor: BRAND.creamCard,
  };
  return (
    <div className="relative">
      <span className="absolute right-3 top-3.5" style={{ color: BRAND.brownSoft }}>
        {icon}
      </span>
      {textarea ? (
        <textarea
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          rows={2}
          style={commonStyle}
          className="w-full rounded-xl border pr-10 pl-3 py-3 text-sm outline-none focus:ring-2"
        />
      ) : (
        <input
          type={type}
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          required={required}
          style={commonStyle}
          className="w-full rounded-xl border pr-10 pl-3 py-3 text-sm outline-none focus:ring-2"
        />
      )}
    </div>
  );
}
